def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, datetime.time):
        raise TypeError("Expected a datetime.time object, got {}".format(type(value)))
    return value.isoformat()

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise ValueError("Expected a Point instance")
    return {
        "lat": value.lat,
        "lon": value.lon,
        "time": value.time.isoformat()
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    try:
        if hasattr(self, '_record') and self._record is not None:
            return list(self._record.keys())
        else:
            raise AttributeError("Record is not set or is None")
    except Exception as e:
        raise RuntimeError(f"An error occurred while retrieving keys: {str(e)}")

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("Protocol version must be provided as a tuple")

    # Example dictionary of protocol handlers
    protocol_handlers_map = {
        (3, 5): cls.ProtocolHandlerV3_5,
        (4, 0): cls.ProtocolHandlerV4_0,
    }

    if protocol_version is None:
        return protocol_handlers_map
    else:
        return {protocol_version: protocol_handlers_map[protocol_version]} if protocol_version in protocol_handlers_map else {}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f'Key {key} not found in data')

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    try:
        if not keys:
            return list(self._record.values())
        else:
            return [self._record[key] for key in keys if key in self._record]
    except AttributeError:
        raise ValueError("The record is not properly initialized or is not a dictionary.")
    except TypeError:
        raise ValueError("Invalid arguments provided; expected keys to be indexes or keys present in the record.")

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        return dict(self._data_dict)

    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._data_dict):
                raise IndexError(f"Index {key} is out of bounds")
            result[list(self._data_dict.keys())[key]] = self._data_dict[list(self._data_dict.keys())[key]]
        elif key in self._data_dict:
            result[key] = self._data_dict[key]
        else:
            result[key] = None

    return result

def pop_u16(self):
    """ Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    try:
        data = self.data[-2:]
        if len(data) != 2:
            raise ValueError("Insufficient data to pop a 16-bit integer")
        self.data = self.data[:-2]
        return int.from_bytes(data, byteorder='big', signed=False)
    except Exception as e:
        raise Exception(f"Error popping u16: {e}")

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not isinstance(name, str) or not name.isidentifier():
        raise ValueError(f"Name must be a valid identifier: {name!r}")
    if not isinstance(fields, (list, tuple)):
        raise ValueError(f"Fields must be a list or tuple: {fields!r}")
    if not isinstance(srid_map, dict):
        raise ValueError(f"SRID map must be a dictionary: {srid_map!r}")

    # Validate fields
    for field in fields:
        if not isinstance(field, str) or not field.isidentifier():
            raise ValueError(f"Field names must be valid identifiers: {field!r}")

    # Create the class
    namespace = {
        '__slots__': tuple(fields),
        '__init__': lambda self, *args: [setattr(self, field, arg) for field, arg in zip(fields, args)],
        '__repr__': lambda self: f"{name}({', '.join(f'{field}={getattr(self, field)!r}' for field in fields)})",
        'srid_map': srid_map,
    }

    return type(name, (Point,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        import warnings
        import functools

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                message,
                category=DeprecationWarning,
                stacklevel=2
            )
            return func(*args, **kwargs)

        return wrapper

    return decorator

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except TypeError:
                    pass  # key is not hashable or value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except TypeError:
                    pass  # key is not hashable or value too large
                return v
        return wrapper
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    if maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")

    def decorator(func):
        cache = {}
        order = []

        def wrapper(*args, **kwargs):
            key = (args, kwargs) if not typed else (args, tuple(sorted(kwargs.items())))
            try:
                result = cache[key]
                order.remove(key)
                order.append(key)
                return result
            except KeyError:
                result = func(*args, **kwargs)
                if len(cache) >= maxsize:
                    oldest_key = order.pop(0)
                    del cache[oldest_key]
                cache[key] = result
                order.append(key)
                return result

        wrapper.cache_info = lambda: (len(cache), maxsize, 0, 0)  # hits, maxsize, misses, currsize
        wrapper.cache_clear = cache.clear
        wrapper.cache_pop = lambda: order.pop() if order else None
        return functools.wraps(func)(wrapper)

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        # Use the oldest key in the dictionary, assuming the dict maintains insertion order
        first_key = next(iter(self))
        first_value = self.pop(first_key)
        return (first_key, first_value)
    except StopIteration:
        raise KeyError('popitem(): dictionary is empty')

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    try:
        value = self._dict.get(key)
        if value is None:
            value = default
            self._dict[key] = value
        return value
    except AttributeError:
        raise TypeError("setdefault method called on a non-dictionary object")
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred: {e}")

def get(self, key, default=None):
    """D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None."""
    try:
        return self.__getitem__(key)
    except KeyError:
        return default

