                    v = method(self, *args, **kwargs)
                except Exception as e:
                    raise RuntimeError(f"Method execution failed: {e}")
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                except Exception as e:
                    raise ValueError(f"Storing value into cache failed: {e}")
                return v
        else:
            def wrapper(self, *args, **kwargs):
                try:
                    c = cache(self)
                except Exception as e:
                    raise ValueError(f"Cache retrieval failed: {e}")
