@staticmethod
def is_file_exist(file_name):
    """
    Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False

    try:
        return os.path.isfile(file_name)
    except IOError:
        return False

@classmethod
def _reset_logging(cls):
    """
    Reset the logging configuration to its default state.
    """
    try:
        logging.shutdown()
        for handler in list(logging.root.handlers):
            logging.root.removeHandler(handler)
        logging.basicConfig(level=logging.WARNING)
    except Exception as e:
        print(f"An error occurred while resetting logging: {e}")

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    try:
        # Example implementation: Remove 'Py' or 'Fallback' suffix from the class name
        class_name = self.__class__.__name__
        if class_name.endswith('Py'):
            return class_name[:-2]
        elif class_name.endswith('Fallback'):
            return class_name[:-8]
        else:
            return class_name
    except Exception as e:
        raise RuntimeError(f"Error determining target class: {e}")

def directlyProvidedBy(object): # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        return object.__provides__
    except AttributeError:
        from zope.interface import implementedBy
        return implementedBy(object)

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    try:
        if not hasattr(self, '_interface'):
            raise AttributeError("Interface not properly initialized or defined.")

        attributes = self._interface
        result = {}

        for name, description in attributes.items():
            if all or description:
                result[name] = description

        return result

    except AttributeError as e:
        print(f"Error accessing interface attributes: {e}")
        return {}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {}

def names(self, all=False): # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    try:
        if all:
            return dir(self)
        else:
            return [attr for attr in dir(self) if not attr.startswith('_')]
    except Exception as e:
        raise RuntimeError(f"An error occurred while retrieving attribute names: {e}")

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if not hasattr(sequence, '__iter__') or isinstance(sequence, str):
        raise ValueError("Argument `sequence` is not iterable or is a string")

    for item in sequence:
        if hasattr(item, '__bases__') and (InterfaceClass in item.__mro__ or Implements in item.__mro__):
            output.append(item)
        elif isinstance(item, tuple):
            _normalizeargs(item, output)
        else:
            raise ValueError("Each item in `sequence` must be an interface, implements spec, or a tuple")

    return output

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if hasattr(self, 'initial_value'):
        self.bins = [self.initial_value for _ in self.bins]
    else:
        self.bins = self.make_bins()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    try:
        coord_errors = getattr(self, f'{coord_name}_errors')
        return [i for i, err in enumerate(coord_errors) if np.isnan(err) or np.isinf(err)]
    except AttributeError:
        raise ValueError(f"No error data found for coordinate: {coord_name}")
    except Exception as e:
        raise RuntimeError(f"An error occurred while retrieving error indices for coordinate {coord_name}: {str(e)}")

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    try:
        if not hasattr(context, 'error'):
            context.error = {}

        # Assuming self.error_indices is a dictionary containing error indices
        if hasattr(self, 'error_indices'):
            context.error.update(self.error_indices)

        # Assuming self.values is a dictionary containing graph data
        if hasattr(self, 'values'):
            if not hasattr(context, 'value'):
                context.value = {}
            context.value.update(self.values)

    except AttributeError as e:
        print(f"Error updating context: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    from collections.abc import Iterable

    def is_fill_request(item):
        return isinstance(item, FillRequest)

    def is_source(item):
        return isinstance(item, Source)

    if not isinstance(seq, Iterable) or isinstance(seq, Source):
        return False

    if is_fill_request(seq):
        return True

    return any(is_fill_request(item) for item in seq if not is_source(item))

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    try:
        fill_method = getattr(obj, 'fill')
        request_method = getattr(obj, 'request')
    except AttributeError:
        return False

    return callable(fill_method) and callable(request_method)

def is_run_el(obj):
    """Object contains executable method 'run'."""
    try:
        return callable(getattr(obj, 'run', None))
    except AttributeError:
        return False

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    try:
        has_fill = callable(getattr(obj, 'fill', None))
        has_compute = callable(getattr(obj, 'compute', None))
        return has_fill and has_compute
    except Exception:
        return False

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both arguments must be dictionaries")

    diff = {}
    for key, value1 in d1.items():
        if key not in d2:
            diff[key] = value1
        else:
            value2 = d2[key]
            if isinstance(value1, dict) and isinstance(value2, dict):
                sub_diff = difference(value1, value2, level - 1)
                if sub_diff:
                    diff[key] = sub_diff
            elif value1 != value2:
                diff[key] = value1

    return diff

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, (tuple, list)):
        raise ValueError("coord must be a tuple or list")
    if len(coord) != len(self.edges) - 1:
        raise ValueError("coord must have the same number of dimensions as the histogram")

    index = []
    for i, c in enumerate(coord):
        index.append(np.searchsorted(self.edges[i], c, side='right') - 1)

    if any(idx < 0 or idx >= len(self.values[i]) for i, idx in enumerate(index)):
        # Coordinate is outside the histogram edges
        return

    # Update the histogram value at the specified coordinate
    current_value = self.values
    for i in index[:-1]:
        current_value = current_value[i]
    current_value[index[-1]] += weight

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re
    from collections.abc import Iterable

    key_regex = re.compile(r'^[a-zA-Z0-9_\-\.]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_\-\.]+(/[\w\.-]+)*$')

    errors = []

    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'Expected a dictionary'}])

    for key, value in labels.items():
        key_str = str(key)
        value_str = str(value)

        if not isinstance(key, (str, int)):
            errors.append({key_str: 'expected string or bytes-like object'})

        if not key_regex.match(key_str):
            errors.append({key_str: f"Label key '{key_str}' does not match the regex {key_regex.pattern}"})

        if not isinstance(value, (str, int, Iterable)):
            errors.append({value_str: 'expected string or bytes-like object'})

        if isinstance(value, (str, int)):
            if not value_regex.match(value_str):
                errors.append({value_str: f"Label value '{value_str}' does not match the regex {value_regex.pattern}"})
        elif isinstance(value, Iterable):
            for item in value:
                item_str = str(item)
                if not isinstance(item, (str, int)):
                    errors.append({item_str: 'expected string or bytes-like object'})
                if not value_regex.match(item_str):
                    errors.append({item_str: f"Label value '{item_str}' does not match the regex {value_regex.pattern}"})

    if errors:
        raise ValidationError(errors)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise ValueError("manifest_dict must be a dictionary")

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = [generate_default_observer_schema_dict(item) if isinstance(item, dict) else None for item in value]
        else:
            if first_level and key in ["apiVersion", "kind", "metadata"]:
                observer_schema[key] = value
            else:
                observer_schema[key] = None
    return observer_schema

def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(last_applied_manifest, list) or not isinstance(observer_schema, list) or not isinstance(response, list):
        raise ValueError("All arguments must be of type list")

    min_length = min(len(observer_schema), len(response))

    for i in range(min_length):
        schema_item = observer_schema[i]
        response_item = response[i]

        if isinstance(schema_item, dict) and isinstance(last_applied_manifest[i], dict) and isinstance(response_item, dict):
            # If the schema item is a dictionary, we assume the last_applied_manifest and response items are also dictionaries
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], schema_item, response_item)
        else:
            # Otherwise, we directly initialize the value from the response if it's not already present
            if i >= len(last_applied_manifest):
                last_applied_manifest.append(response_item)
            elif last_applied_manifest[i] is None:
                last_applied_manifest[i] = response_item

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Helper function to update a partial ``last_applied_manifest`` dictionary
    from a partial Kubernetes response dictionary based on the given schema.

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.
    """
    for key, schema_value in observer_schema.items():
        if key not in last_applied_manifest:
            last_applied_manifest[key] = response.get(key, None)
        elif schema_value and isinstance(schema_value, dict) and isinstance(last_applied_manifest[key], dict) and response.get(key) is not None:
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[key], schema_value, response[key])
        elif isinstance(schema_value, list) and isinstance(last_applied_manifest[key], list) and response.get(key) is not None:
            if len(last_applied_manifest[key]) < len(response[key]):
                last_applied_manifest[key].extend([None] * (len(response[key]) - len(last_applied_manifest[key])))
            update_last_applied_manifest_list_from_resp(last_applied_manifest[key], schema_value, response[key])

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(last_applied_manifest, dict):
        raise ValueError("last_applied_manifest must be a dictionary")
    if not isinstance(observer_schema, dict):
        raise ValueError("observer_schema must be a dictionary")
    if not isinstance(response, dict):
        raise ValueError("response must be a dictionary")

    for field, schema in observer_schema.items():
        if field not in response:
            raise KeyError(f"The observed field '{field}' is not present in the Kubernetes response")

        if field not in last_applied_manifest:
            last_applied_manifest[field] = response[field]
        elif isinstance(schema, dict) and isinstance(last_applied_manifest[field], dict) and isinstance(response[field], dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], schema, response[field])
        elif isinstance(schema, list) and isinstance(last_applied_manifest[field], list) and isinstance(response[field], list):
            # Assuming list items are dictionaries and the list in schema is non-empty for structure reference
            if schema and isinstance(schema[0], dict):
                for item in response[field]:
                    item_key = next(iter(item))  # Assuming each item is a dict with a unique key
                    if not any(item_key in subitem for subitem in last_applied_manifest[field]):
                        last_applied_manifest[field].append(item)
                    else:
                        for manifest_item in last_applied_manifest[field]:
                            if item_key in manifest_item:
                                update_last_applied_manifest_dict_from_resp(manifest_item[item_key], schema[0], item[item_key])
        # Add more complex handling if needed for other data structures in schema

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        raise ValueError("The provided application object does not have a spec or manifest attribute")

    default_schema = {}
    for resource_kind, manifest in app.spec.manifest.items():
        if resource_kind not in app.spec.observer_schema:
            # Example default schema, this should be adjusted to fit the actual requirements
            default_schema[resource_kind] = {
                "observed_fields": ["status", "spec"],
                "rescheduling_conditions": ["status.conditions.type=Failed"]
            }

    # Merge default schema with any existing custom schemas
    if not app.spec.observer_schema:
        app.spec.observer_schema = default_schema
    else:
        app.spec.observer_schema.update(default_schema)

    return app.spec.observer_schema

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
    """
    if isinstance(params, Mapping):
        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style

        try:
            if in_style == 'named' and out_style == 'qmark':
                new_params = []
                new_sql = re.sub(r':(\w+)', lambda m: '?', sql)
                for key in re.findall(r':(\w+)', sql):
                    new_params.append(params[key])
                return new_sql, new_params
            elif in_style == 'named' and out_style == 'numeric':
                new_params = []
                new_sql = sql
                for i, key in enumerate(re.findall(r':(\w+)', sql)):
                    new_sql = new_sql.replace(f':{key}', f':{i + 1}')
                    new_params.append(params[key])
                return new_sql, new_params
            elif in_style == 'named' and out_style == 'named':
                return sql, params
            elif in_style == 'qmark' and out_style == 'named':
                new_params = {}
                new_sql = sql
                for i, param in enumerate(params):
                    new_params[f'param{i + 1}'] = param
                    new_sql = new_sql.replace('?', f':param{i + 1}')
                return new_sql, new_params
            elif in_style == 'qmark' and out_style == 'numeric':
                return sql, list(params)
            elif in_style == 'qmark' and out_style == 'qmark':
                return sql, list(params)
            elif in_style == 'numeric' and out_style == 'named':
                new_params = {}
                new_sql = sql
                for i, param in enumerate(params):
                    new_params[f'param{i + 1}'] = param
                    new_sql = new_sql.replace(f':{i + 1}', f':param{i + 1}')
                return new_sql, new_params
            elif in_style == 'numeric' and out_style == 'qmark':
                new_sql = sql
                for i, param in enumerate(params):
                    new_sql = new_sql.replace(f':{i + 1}', '?')
                return new_sql, list(params)
            elif in_style == 'numeric' and out_style == 'numeric':
                return sql, list(params)
            else:
                raise ValueError("Unsupported parameter style conversion")
        except (KeyError, IndexError) as e:
            raise ValueError("Parameter mismatch in SQL query") from e
    elif isinstance(params, Sequence):
        in_style = self.SQLParams.in_style
        out_style = self.SQLParams.out_style

        try:
            if in_style == 'qmark' and out_style == 'named':
                new_params = {}
                new_sql = sql
                for i, param in enumerate(params):
                    new_params[f'param{i + 1}'] = param
                    new_sql = new_sql.replace('?', f':param{i + 1}')
                return new_sql, new_params
            elif in_style == 'qmark' and out_style == 'numeric':
                return sql, list(params)
            elif in_style == 'qmark' and out_style == 'qmark':
                return sql, list(params)
            elif in_style == 'numeric' and out_style == 'named':
                new_params = {}
                new_sql = sql
                for i, param in enumerate(params):
                    new_params[f'param{i + 1}'] = param
                    new_sql = new_sql.replace(f':{i + 1}', f':param{i + 1}')
                return new_sql, new_params
            elif in_style == 'numeric' and out_style == 'qmark':
                new_sql = sql
                for i, param in enumerate(params):
                    new_sql = new_sql.replace(f':{i + 1}', '?')
                return new_sql, list(params)
            elif in_style == 'numeric' and out_style == 'numeric':
                return sql, list(params)
            else:
                raise ValueError("Unsupported parameter style conversion")
        except IndexError as e:
            raise ValueError("Parameter mismatch in SQL query") from e
    else:
        raise TypeError("params must be a Mapping or Sequence")

