def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not isinstance(manifest_files, (list, tuple)):
        raise ValueError("manifest_files must be a list or tuple")
    if not isinstance(digests_used, dict):
        raise ValueError("digests_used must be a dictionary")

    for manifest_file in manifest_files:
        if not isinstance(manifest_file, dict):
            raise ValueError("Each manifest file entry must be a dictionary")
        required_digests = manifest_file.get('required_digests', [])
        if not isinstance(required_digests, (list, tuple)):
            raise ValueError("required_digests must be a list or tuple")

        for digest in required_digests:
            if not isinstance(digest, str):
                raise ValueError("Each digest must be a string")
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} is required but not present in digests_used")
            if not digests_used[digest]:
                raise ValueError(f"Digest {digest} is present but not used")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise TypeError("The 'prior' parameter must be an instance of InventoryValidator")

    if self.inventory.keys() != prior.inventory.keys():
        raise ValueError("The 'prior' inventory must have the same items as the current inventory")

    for item, current_value in self.inventory.items():
        prior_value = prior.inventory[item]
        if not isinstance(prior_value, (int, float)) or not isinstance(current_value, (int, float)):
            raise ValueError(f"Both current and prior values for item '{item}' must be numeric")
        if prior_value > current_value:
            raise ValueError(f"The 'prior' inventory value for item '{item}' cannot exceed the current inventory value")

    # Additional checks can be added here if necessary
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    if version not in inventory:
        raise KeyError(f"Version '{version}' not found in inventory.")

    path_map = {}
    for logical_path, details in inventory.get(version, {}).items():
        if not isinstance(details, dict) or 'content_files' not in details:
            raise ValueError(f"Invalid entry for version '{version}' in inventory.")
        path_map[logical_path] = set(details['content_files'])

    return path_map

