def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            op, *operands = expr
            if op == '&':
                if operands[1] == ('|', operands[0], operands[2]):
                    return operands[0]
                elif operands[1] == ('|', operands[2], operands[0]):
                    return operands[0]
                elif operands[1] == ('|', ('~', operands[0]), operands[2]):
                    return ('&', operands[0], operands[2])
                elif operands[1] == ('|', operands[2], ('~', operands[0])):
                    return ('&', operands[0], operands[2])
            elif op == '|':
                if operands[1] == ('&', operands[0], operands[2]):
                    return operands[0]
                elif operands[1] == ('&', operands[2], operands[0]):
                    return operands[0]
                elif operands[1] == ('&', ('~', operands[0]), operands[2]):
                    return ('|', operands[0], operands[2])
                elif operands[1] == ('&', operands[2], ('~', operands[0])):
                    return ('|', operands[0], operands[2])
        return expr

    if not isinstance(args, list):
        raise ValueError("args must be a list of expressions")

    return [apply_absorption(arg) for arg in args]

def normalized(self):
    """
    Return a version of this object represented entirely using integer
    values for the relative attributes.

    >>> relativedelta(days=1.5, hours=2).normalized()
    relativedelta(days=+1, hours=+14)

    :return:
        Returns a :class:`dateutil.relativedelta.relativedelta` object.
    """
    kwargs = {}
    for attr in ['years', 'months', 'days', 'leapdays', 'weeks', 'hours', 'minutes', 'seconds', 'microseconds']:
        value = getattr(self, attr)
        if isinstance(value, float):
            value = int(value)
        kwargs[attr] = value

    # Normalize fractions of larger units to smaller units
    # For example, 1.5 days -> 1 day + 12 hours
    if 'days' in kwargs and kwargs['days'] != int(kwargs['days']):
        kwargs['days'], sub_days = divmod(kwargs['days'], 1)
        kwargs['hours'] = kwargs.get('hours', 0) + int(sub_days * 24)

    if 'hours' in kwargs and kwargs['hours'] != int(kwargs['hours']):
        kwargs['hours'], sub_hours = divmod(kwargs['hours'], 1)
        kwargs['minutes'] = kwargs.get('minutes', 0) + int(sub_hours * 60)

    if 'minutes' in kwargs and kwargs['minutes'] != int(kwargs['minutes']):
        kwargs['minutes'], sub_minutes = divmod(kwargs['minutes'], 1)
        kwargs['seconds'] = kwargs.get('seconds', 0) + int(sub_minutes * 60)

    if 'seconds' in kwargs and kwargs['seconds'] != int(kwargs['seconds']):
        kwargs['seconds'], sub_seconds = divmod(kwargs['seconds'], 1)
        kwargs['microseconds'] = kwargs.get('microseconds', 0) + int(sub_seconds * 1_000_000)

    return relativedelta(**kwargs)

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        try:
            result = namefunc(*args, **kwargs)
            if isinstance(result, tuple):
                return tuple(item.encode('utf-8') if isinstance(item, str) else item for item in result)
            elif isinstance(result, str):
                return result.encode('utf-8')
            else:
                return result
        except Exception as e:
            raise RuntimeError(f"An error occurred while processing the function: {e}")
    return inner_func

