def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    from subprocess import PIPE

    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings.")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings.")

    full_command = commands + args
    stdout = PIPE
    stderr = PIPE if hide_stderr else None

    try:
        process = subprocess.Popen(full_command, cwd=cwd, env=env, stdout=stdout, stderr=stderr)
        output, error = process.communicate()
        if process.returncode != 0:
            if verbose:
                print(f"Command failed with return code {process.returncode}")
            if error:
                raise subprocess.CalledProcessError(process.returncode, full_command, error.decode())
            else:
                raise subprocess.CalledProcessError(process.returncode, full_command)
        if verbose:
            print(f"Command executed successfully with return code {process.returncode}")
            if output:
                print(output.decode())
        return output.decode() if output else None
    except Exception as e:
        raise Exception(f"An error occurred while running the command: {e}")

