def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str) or not isinstance(method, str):
        raise ValueError("Both vcs and method parameters must be strings.")

    def decorate(f):
        """Store f in HANDLERS[vcs][method]."""
        if 'HANDLERS' not in globals():
            global HANDLERS
            HANDLERS = {}
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        if method in HANDLERS[vcs]:
            raise RuntimeError(f"A handler for method '{method}' with VCS '{vcs}' is already registered.")
        HANDLERS[vcs][method] = f
        return f
    return decorate

