    root_inventory = {}  # Placeholder for the root inventory, assume it's loaded or provided elsewhere
    try:
        with open(os.path.join(version_dirs[0], 'inventory'), 'r') as f:
            root_inventory = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        raise ValueError(f"Failed to load root inventory: {e}")

    content_digest_mismatches = {}

    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, 'inventory')
        try:
            with open(inventory_path, 'r') as f:
                current_inventory = json.load(f)
        except (FileNotFoundError, json.JSONDecodeError) as e:
            raise ValueError(f"Failed to load inventory for version {version_dir}: {e}")

        for item, digest in current_inventory.items():
            if item in root_inventory and root_inventory[item] != digest:
                if version_dir not in content_digest_mismatches:
                    content_digest_mismatches[version_dir] = {}
                content_digest_mismatches[version_dir][item] = digest

    return content_digest_mismatches

def amend_bzparams(self, params, bug_ids):
