def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    if number < 0:
        raise ValueError("Number must be non-negative.")

    base = len(alphabet)
    if base < 2:
        raise ValueError("Alphabet must contain at least two distinct characters.")

    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    digits = []
    while number:
        number, remainder = divmod(number, base)
        digits.append(alphabet[remainder])

    result = ''.join(reversed(digits))

    if padding is not None and len(result) < padding:
        result = alphabet[0] * (padding - len(result)) + result

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError("flow_params must be a dictionary")
    if not isinstance(register_number, int):
        raise TypeError("register_number must be an integer")
    if not isinstance(register_value, str):
        raise TypeError("register_value must be a string")

    for flow in flow_params.values():
        if isinstance(flow, dict):
            for key in list(flow.keys()):
                if key == register_value:
                    flow[register_number] = flow.pop(key)
                elif isinstance(flow[key], dict):
                    _replace_register(flow[key], register_number, register_value)
                elif isinstance(flow[key], list):
                    for i, item in enumerate(flow[key]):
                        if isinstance(item, dict):
                            _replace_register(item, register_number, register_value)

    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("value must be a string")
    if not isinstance(arg, str):
        raise ValueError("arg must be a string")
    return value.replace('.', arg)

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        sc = c.__subclasses__()
        for subcls in sc:
            if subcls not in seen:
                seen.add(subcls)
                queue.append(subcls)

    seen.remove(cls)
    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty.")

    base = len(alphabet)
    inverse_alphabet = {char: index for index, char in enumerate(alphabet)}

    number = 0
    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Character '{char}' not found in the provided alphabet.")
        number = number * base + inverse_alphabet[char]

    return number

def regex_dict(item):
    """
    Convert *.cpp keys to regex keys

    Given a dict where the keys are all filenames with wildcards, convert only
    the keys into equivalent regexes and leave the values intact.

    Example:

    rules = {
        '*.cpp':
            {'a': 'arf', 'b': 'bark', 'c': 'coo'},
        '*.h':
            {'h': 'help'}
    }
    regex_keys = regex_dict(rules)

    Args:
        item: dict to convert
    Returns:
        dict with keys converted to regexes
    """
    regex_patterns = {
        '*.cpp': r'^.*\.cpp$',
        '*.h': r'^.*\.h$'
    }
    return {re.compile(regex_patterns.get(k, k)): v for k, v in item.items()}

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise ValueError("Input must be a string.")
    try:
        # Remove leading and trailing single or double quotes
        return re.sub(r'^["\']|["\']$', '', name)
    except TypeError as e:
        raise ValueError("Error processing the input string.") from e

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import re
    import sys

    def posix_split(s):
        return re.findall(r"""(?:[^\s\\']|\\[-\\ ]|'(?:[^'\\]|\\.)*')""", s)

    def windows_split(s):
        return re.findall(r"""(?:[^\s"]|"(?:[^"\\]|\\.)*")""", s)

    if platform == 'this':
        platform = 1 if sys.platform != 'win32' else 0

    if platform == 1:
        return posix_split(s)
    elif platform == 0:
        return windows_split(s)
    else:
        raise ValueError("Invalid platform specified. Use 'this', 0, or 1.")

def addignored(ignored):
    ''' Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        output = subprocess.check_output(['git', 'check-ignore', '-v'] + ignored, stderr=subprocess.STDOUT).decode('utf-8').strip()
        if not output:
            return ''
        ignored_files = [line.split()[-1] for line in output.splitlines()]
        sorted_ignored_files = sorted(set(ignored_files))
        return ','.join(sorted_ignored_files)
    except subprocess.CalledProcessError as e:
        raise Exception(f"Error retrieving ignored files: {e.output.decode('utf-8').strip()}")

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Get the list of addresses for the host
        resolved_addresses = socket.getaddrinfo(host, None, flags=socket.AI_NUMERICHOST)
        # Extract just the IP addresses from the results
        ip_addresses = {info[-1][0] for info in resolved_addresses}
        # Check if any of the resolved addresses are loopback addresses
        return any(ip.startswith('127.') or ip == '::1' for ip in ip_addresses)
    except socket.gaierror:
        # If the host cannot be resolved, assume it's not localhost
        return False

def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    def is_pattern(path):
        return bool(re.search(r'[\*\?\[\]]', path))

    transformed_paths = []
    for path in find_paths:
        if is_pattern(path):
            transformed_paths.append(path)
        else:
            transformed_paths.append(f'sh:**/{path}/**')
    return transformed_paths

