def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    if not isinstance(commands, list) or not all(isinstance(cmd, str) for cmd in commands):
        raise ValueError("commands must be a list of strings")
    if not isinstance(args, list) or not all(isinstance(arg, str) for arg in args):
        raise ValueError("args must be a list of strings")

    full_command = commands + args
    try:
        if verbose:
            print("Running command: {}".format(' '.join(full_command)))

        stderr = subprocess.PIPE if hide_stderr else None
        process = subprocess.Popen(full_command, cwd=cwd, env=env, stderr=stderr, stdout=subprocess.PIPE)
        stdout, stderr_output = process.communicate()

        if process.returncode != 0:
            error_message = f"Command failed with return code {process.returncode}."
            if stderr_output:
                error_message += f" Error: {stderr_output.decode('utf-8')}"
            raise subprocess.CalledProcessError(returncode=process.returncode, cmd=full_command, output=stdout, stderr=stderr_output)

        if verbose and stdout:
            print("Output: {}".format(stdout.decode('utf-8')))

        return stdout.decode('utf-8')

    except subprocess.CalledProcessError as e:
        raise
    except Exception as e:
        raise RuntimeError(f"An error occurred while running the command: {e}")

