def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import toml
    import os

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Configuration file {filename} does not exist.", args=(), exc_info=None))
            continue

        try:
            with open(filename, 'r') as file:
                raw_config = file.read()
                config = toml.loads(raw_config)
                config_dict[filename] = config
        except Exception as e:
            log_records.append(logging.LogRecord(name='config_loader', level=logging.ERROR, pathname=filename, lineno=0, msg=f"Failed to parse configuration file {filename}: {str(e)}", args=(), exc_info=e))

    if overrides:
        for key, value in overrides.items():
            for config in config_dict.values():
                config[key] = value

    if resolve_env:
        import re
        env_var_pattern = re.compile(r'\$\{(\w+)\}')
        for filename, config in config_dict.items():
            for key, value in config.items():
                if isinstance(value, str):
                    matches = env_var_pattern.findall(value)
                    for match in matches:
                        env_value = os.getenv(match)
                        if env_value is not None:
                            value = value.replace(f'${{{match}}}', env_value)
                            config[key] = value
                        else:
                            log_records.append(logging.LogRecord(name='config_loader', level=logging.WARNING, pathname=filename, lineno=0, msg=f"Environment variable {match} not found for key {key}.", args=(), exc_info=None))

    return config_dict, log_records

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    try:
        if isinstance(obj, str):
            return obj.encode('utf-8')
        elif isinstance(obj, bytes):
            return obj
        else:
            raise ValueError("Input must be a string or bytes-like object.")
    except Exception as e:
