def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple, bytes)):
        return (seq, type(seq))
    else:
        try:
            # Attempt to convert to a list if it's an iterable
            sequence = list(seq)
            return (sequence, type(sequence))
        except TypeError:
            # If seq is not iterable, return it as is with its type
            return (seq, type(seq))

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not iface or not candidate:
        raise ValueError("Both iface and candidate must be provided.")

    try:
        if tentative:
            return iface.providedBy(candidate)
        else:
            return iface.implementedBy(candidate)
    except AttributeError:
        raise TypeError("iface must be an interface and candidate must be a class or instance.")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc:
        return explicit_mc

    metaclasses = set()
    for base in bases:
        try:
            metaclass = type(base)
            if metaclass not in (type, object):
                metaclasses.add(metaclass)
        except TypeError:
            continue

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there's more than one metaclass, we need to find a common base
    metaclass = metaclasses.pop()
    for other_mc in metaclasses:
        metaclass = metaclass.__class__.__mro__[-1]
        other_mc_mro = other_mc.__class__.__mro__[-1]
        if not issubclass(metaclass, other_mc_mro) and not issubclass(other_mc_mro, metaclass):
            raise TypeError("metaclass conflict: the metaclass of a derived class must be a (non-strict) subclass of the metaclasses of all its bases")

    return metaclass

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('dictionary is empty')

    # Find the least frequently used item
    min_frequency = float('inf')
    lfu_key = None
    for key, (value, frequency) in self._cache.items():
        if frequency < min_frequency:
            min_frequency = frequency
            lfu_key = key

    # In case of frequency tie, remove the least recently used among them
    if lfu_key is not None:
        for key, (value, frequency) in self._cache.items():
            if frequency == min_frequency:
                if lfu_key not in self._access_order or key in self._access_order and self._access_order.index(key) < self._access_order.index(lfu_key):
                    lfu_key = key

    if lfu_key is None:
        raise KeyError('dictionary is empty')

    # Remove the least frequently used item
    lfu_value, _ = self._cache.pop(lfu_key)
    self._access_order.remove(lfu_key)
    return lfu_key, lfu_value

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('dictionary is empty')
    key = next(reversed(self))
    value = self.pop(key)
    return (key, value)

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    import random
    try:
        key = random.choice(list(self.keys()))
        value = self.pop(key)
        return (key, value)
    except IndexError:
        raise KeyError('dictionary is empty')

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter = _converting._Converter()
    except Exception as e:
        raise RuntimeError("Failed to create parameter style converter") from e
    return converter

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Legacy payload check
    try:
        if "diaspora" in request.headers.get("User-Agent", ""):
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        # Check if the request contains the expected Matrix-specific header
        user_agent = request.headers.get('User-Agent', '')
        if 'Matrix' in user_agent:
            return True

        # Check if the request path follows Matrix API conventions
        path = request.path
        if path.startswith('/_matrix/'):
            return True

        # Check for Matrix-specific query parameters
        if 'access_token' in request.args:
            return True

    except Exception as e:
        # Log the exception or handle it as needed
        pass

    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    try:
        if dt is None:
            return None
        if not hasattr(dt, 'strftime'):
            raise ValueError("Input must be a datetime object.")
        return dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    except (TypeError, ValueError) as e:
        raise ValueError(f"Error formatting datetime: {e}")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("'tag' expects a string")
    # Assuming a valid tag contains only alphanumeric characters and underscores
    if len(tag) == 0 or not tag.replace('_', '').isalnum():
        return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversion - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag not in result:
            result[tag] = child.text
        else:
            if not isinstance(result[tag], list):
                result[tag] = [result[tag]]
            result[tag].append(child.text)
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("URL is required")

    if not url.startswith(('http://', 'https://')):
        raise ValueError("URL must start with http:// or https://")

    if not document_path:
        document_path = "/nodeinfo/1.0"

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": url + document_path
            }
        ]
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json
        from xml.etree import ElementTree as ET

        # Attempt to parse as JSON
        try:
            data = json.loads(document)
            return {
                'hcard_url': data.get('links')[0].get('href') if data.get('links') else None,
                'subject': data.get('subject'),
                'aliases': data.get('aliases', [])
            }
        except (json.JSONDecodeError, IndexError, TypeError):
            pass

        # Attempt to parse as XRD
        try:
            root = ET.fromstring(document)
            xrd_namespace = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
            hcard_url = root.find('.//xrd:Link[@rel="http://webfinger.net/rel/hcard"]', xrd_namespace)
            subject = root.find('.//xrd:Subject', xrd_namespace)
            aliases = root.findall('.//xrd:Alias', xrd_namespace)

            return {
                'hcard_url': hcard_url.attrib['href'] if hcard_url is not None else None,
                'subject': subject.text if subject is not None else None,
                'aliases': [alias.text for alias in aliases] if aliases else []
            }
        except (ET.ParseError, KeyError):
            pass

    except Exception as e:
        logger.warning("parse_diaspora_webfinger: failed to parse document: %s", str(e))

    return {}

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if "@" not in handle:
            logger.warning("try_retrieve_webfinger_document: invalid handle given: %s", handle)
            return None
        host = handle.split("@")[1]
        url = f"https://{host}/.well-known/webfinger?resource=acct:{quote(handle)}"
        with closing(urllib.request.urlopen(url)) as response:
            return response.read().decode('utf-8')
    except Exception as e:
        logger.warning("try_retrieve_webfinger_document: failed to retrieve webfinger document for handle %s: %s", handle, e)
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except (AttributeError, IndexError):
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if exception:
        logger.warning("retrieve_and_parse_diaspora_webfinger: error fetching document for handle %s: %s", handle, exception)
        return None
    if document:
        try:
            return parse_diaspora_webfinger(document)
        except Exception as e:
            logger.warning("retrieve_and_parse_diaspora_webfinger: error parsing document for handle %s: %s", handle, e)
            return None
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        logger.warning("retrieve_and_parse_diaspora_webfinger: could not retrieve host-meta for host %s", host)
        return None
    lrdd_link = hostmeta.find_link(rels="lrdd")
    if not lrdd_link:
        logger.warning("retrieve_and_parse_diaspora_webfinger: no LRDD link found in host-meta for host %s", host)
        return None
    url = lrdd_link.template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        logger.warning("retrieve_and_parse_diaspora_webfinger: error fetching LRDD document for handle %s: %s", handle, exception)
        return None
    try:
        return parse_diaspora_webfinger(document)
    except Exception as e:
        logger.warning("retrieve_and_parse_diaspora_webfinger: error parsing LRDD document for handle %s: %s", handle, e)
        return None

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    method = method.upper()
    headers = CaseInsensitiveDict({
        'User-Agent': USER_AGENT,
    })
    if "headers" in kwargs:
        headers.update(kwargs.get("headers"))
    kwargs.update({
        "data": data,
        "timeout": timeout,
        "headers": headers
    })
    try:
        if method == "POST":
            response = requests.post(url, *args, **kwargs)
        elif method == "GET":
            response = requests.get(url, *args, **kwargs)
        else:
            return None, ValueError("Unsupported method: {}".format(method))
        return response.status_code, None
    except RequestException as ex:
        return None, ex

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    current_dict = dic
    for sub_key in keys[:-1]:
        if sub_key not in current_dict:
            current_dict[sub_key] = {}
        current_dict = current_dict[sub_key]
    if keys:
        current_dict[keys[-1]] = val
    else:
        current_dict[key] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        file_names = []
        for directory in settings_dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                if fname.endswith(spec_option):
                    file_names.append(os.path.join(directory, fname))
        return sorted(file_names)
    except (TypeError, OSError):
        return []

