@classmethod
def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    import yaml

    if spec_content is None:
        raise IRValidatorException("spec_content argument must be supplied")

    try:
        spec_data = yaml.safe_load(spec_content)
    except yaml.YAMLError as e:
        raise IRValidatorException(f"There was a problem parsing the spec content.\n{str(e)}")

    required_fields = ['field1', 'field2', 'field3']  # Replace with actual required fields

    for field in required_fields:
        if field not in spec_data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in the spec file")

    return spec_data

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.load(file, Loader=yaml.SafeLoader)
    except FileNotFoundError:
        raise IRValidatorException(f"File not found: {yaml_file}")
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file: {str(e)}")

    # Example of checking for mandatory fields
    required_fields = {'field1', 'field2', 'field3'}
    missing_fields = required_fields - data.keys()
    if missing_fields:
        raise IRValidatorException(f"Mandatory fields missing from the file: {missing_fields}")

    return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        raise ValueError("parser_dict must be a dictionary")

    for key, value in parser_dict.items():
        if isinstance(value, dict) and 'include' in value:
            include_key = value['include']
            if include_key in parser_dict:
                included_dict = parser_dict[include_key]
                if not isinstance(included_dict, dict):
                    raise ValueError(f"Included value for {include_key} must be a dictionary")
                parser_dict[key].update(included_dict)
                del parser_dict[key]['include']
            else:
                raise KeyError(f"Include key {include_key} not found in parser_dict")
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    try:
        for arg_name, spec_details in self.spec.items():
            if 'default' in spec_details:
                defaults[arg_name] = spec_details['default']
            elif 'env_var' in spec_details:
                import os
                env_value = os.getenv(spec_details['env_var'])
                if env_value is not None:
                    defaults[arg_name] = env_value
            elif 'config_key' in spec_details:
                import configparser
                config = configparser.ConfigParser()
                config.read(spec_details['config_file'])
                if config.has_option('DEFAULT', spec_details['config_key']):
                    defaults[arg_name] = config['DEFAULT'][spec_details['config_key']]
    except Exception as e:
        print(f"An error occurred while resolving defaults: {e}")
    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = getattr(self, '_deprecated_args', {})
    if not isinstance(deprecated_args, dict):
        raise ValueError("Deprecated arguments should be stored in a dictionary.")
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    if not isinstance(cli_args, dict) or not isinstance(answer_file_args, dict):
        raise ValueError("Both cli_args and answer_file_args must be dictionaries.")

    # Define deprecated arguments and their mappings
    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2'
    }

    # Check for deprecated arguments in cli_args
    for deprecated_arg, new_arg in deprecated_args.items():
        if deprecated_arg in cli_args:
            print(f"Warning: The argument '{deprecated_arg}' has been deprecated and will be removed in a future version. Please use '{new_arg}' instead.")

    # Check for deprecated arguments in answer_file_args
    for deprecated_arg, new_arg in deprecated_args.items():
        if deprecated_arg in answer_file_args:
            print(f"Warning: The argument '{deprecated_arg}' has been deprecated and will be removed in a future version. Please use '{new_arg}' instead.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        if not isinstance(command_name, str):
            raise ValueError("command_name must be a string")

        # Assuming self.parsers is a dictionary holding parsers for different commands
        if command_name not in self.parsers:
            raise KeyError(f"No parser found for command: {command_name}")

        parser = self.parsers[command_name]
        options = []

        # Extract options from the parser
        for action in parser._actions:
            if action.option_strings:
                option_info = {
                    'flags': action.option_strings,
                    'dest': action.dest,
                    'type': action.type,
                    'help': action.help,
                    'default': action.default
                }
                options.append(option_info)

        return options

    except Exception as e:
        print(f"An error occurred: {e}")
        return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    try:
        if not isinstance(command_name, str) or not isinstance(argument_name, str):
            raise ValueError("Both command_name and argument_name must be strings.")

        command = self.commands.get(command_name)
        if command is None:
            raise KeyError(f"Command '{command_name}' not found.")

        option_spec = command.options.get(argument_name)
        if option_spec is None:
            raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'.")

        return option_spec
    except (ValueError, KeyError) as e:
        logging.error(e)
        return None

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    if not isinstance(args, argparse.Namespace):
        raise ValueError("Expected args to be an instance of argparse.Namespace")

    silenced_args = []
    for arg in vars(args):
        if arg.startswith('silent_'):
            silenced_args.append(arg)
    return silenced_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if not isinstance(options_spec, list):
        raise TypeError("options_spec must be a list")
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    conditionally_required_args = []
    for option in options_spec:
        required_when = option.get('required_when')
        if required_when:
            condition = required_when.get('condition')
            if not callable(condition):
                raise ValueError("condition must be a callable")
            if condition(command_name=command_name, args=args):
                conditionally_required_args.append(option.get('name'))

    return conditionally_required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    for arg_name, arg_value in args.items():
        if not isinstance(arg_value, dict):
            raise ValueError(f"Argument {arg_name} must be a dictionary")

        value = arg_value.get('value')
        length = arg_value.get('length')

        if value is None or length is None:
            continue

        if not isinstance(value, str):
            raise TypeError(f"Argument {arg_name} value must be a string")

        if not isinstance(length, int):
            raise TypeError(f"Argument {arg_name} length must be an integer")

        if len(value) > length:
            raise ValueError(f"Argument {arg_name} value is longer than specified length ({len(value)} > {length})")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, value in args.items():
        if hasattr(self, 'choices') and arg_name in self.choices:
            available_choices = self.choices[arg_name]
            if value not in available_choices:
                raise ValueError(f"Invalid value for {arg_name}: {value}. Available choices are {available_choices}.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, 'min_value') or not hasattr(self, 'max_value'):
        raise ValueError("Class instance must have 'min_value' and 'max_value' attributes defined.")

    min_value = self.min_value
    max_value = self.max_value

    if not isinstance(args, (list, tuple)):
        raise TypeError("Arguments must be provided as a list or tuple.")

    for arg in args:
        if not isinstance(arg, (int, float)):
            raise TypeError("All arguments must be integers or floats.")
        if not (min_value <= arg <= max_value):
            raise ValueError(f"Argument value {arg} is out of the allowed range [{min_value}, {max_value}].")

    return args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args_prefix = 'custom_'

    try:
        for key, value in args.items():
            if key.startswith(custom_args_prefix):
                # Remove the 'custom_' prefix for custom args
                nested_args[key[len(custom_args_prefix):]] = value
            elif key in ['control_arg1', 'control_arg2']:  # Example control args, replace with actual control args
                control_args[key] = value
            else:
                nested_args[key] = value
    except AttributeError:
        raise ValueError("Args must be a dictionary with string keys.")

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, list):
        raise ValueError("extra_vars must be a list")

    for extra_var in extra_vars:
        if not isinstance(extra_var, dict):
            raise ValueError("Each item in extra_vars must be a dictionary")
        vars_dict.update(extra_var)

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import subprocess

    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"The playbook file does not exist: {playbook_path}")

    command = ["ansible-playbook"]

    if verbose:
        command.extend(["-" + "v" * int(verbose)])

    if extra_vars:
        extra_vars_str = " ".join([f"{k}={v}" for k, v in extra_vars.items()])
        command.extend(["--extra-vars", extra_vars_str])

    if ansible_args:
        for arg, value in ansible_args.items():
            if value is None:
                command.append(f"--{arg}")
            else:
                command.extend([f"--{arg}", str(value)])

    command.append(playbook_path)

    try:
        process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()

        if process.returncode != 0:
            raise RuntimeError(f"Ansible playbook failed with error:\n{stderr.decode()}")

        return stdout.decode()

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"An error occurred while running the Ansible playbook: {e}")
    except Exception as e:
        raise Exception(f"An unexpected error occurred: {e}")

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    # Example parsers and their expected argument types
    parser_configs = {
        'main': {
            'age': int,
            'is_active': bool,
            'name': str
        },
        'virsh': {
            'memory': int,
            'cpus': int,
            'autostart': bool
        },
        'ospd': {
            'port': int,
            'use_ssl': bool,
            'host': str
        }
    }

    if parser_name not in parser_configs:
        raise ValueError(f"Unknown parser_name: {parser_name}")

    config = parser_configs[parser_name]

    for arg, value in values_dict.items():
        if arg in config:
            try:
                values_dict[arg] = config[arg](value)
            except (ValueError, TypeError) as e:
                raise ValueError(f"Failed to convert argument '{arg}' to type {config[arg].__name__}: {e}")

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    try:
        spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
        if not os.path.isfile(spec_path):
            raise ValueError(f"Plugin spec file not found at {spec_path}")

        with open(spec_path, 'r') as file:
            plugin_spec = json.load(file)

        return flatten_dict(plugin_spec)

    except (FileNotFoundError, json.JSONDecodeError, ValueError) as e:
        raise RuntimeError(f"Error reading or parsing plugin spec: {e}")

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if os.getenv('CONFIG_PATH') is None:
        if hasattr(self, 'config_path'):
            os.environ['CONFIG_PATH'] = str(self.config_path)
        else:
            raise ValueError("Config path is not defined in the instance and not set in environment variables.")

def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    if not hasattr(root_subparsers, 'add_parser'):
        raise ValueError("The provided object is not a valid subparser object.")

    parser = root_subparsers.add_parser(self.name, help=self.help)
    for arg in self.args:
        parser.add_argument(*arg.flags, **arg.kwargs)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError("Path does not start with the specified root")
    stripped_path = path[len(root):]
    # Remove any leading os.sep if present after stripping the root
    if stripped_path and stripped_path.startswith(os.sep):
        stripped_path = stripped_path[len(os.sep):]
    return stripped_path
